            with self.server.lock:
                count=int(self.server.state.get('reset_count',0))
                if count>=2:
                    self.server.state['reset_count']=3
                    self.server.state['reset_failed']=True
                    self.server.state.setdefault('events', []).append({'t':self.server.state.get('step',0),'actor':'system','action':'reset','result':'reset_limit_failed','reset_count':3})
                    msg='reset_limit_failed'
                else:
                    self.server.state=fresh();self.server.state['reset_count']=count+1
                    self.server.state.setdefault('events', []).append({'t':0,'actor':'system','action':'reset','result':'reset','reset_count':count+1})
                    msg='reset'
                save(self.server.state_path,self.server.state)
                body=json.dumps({'state':self.public_state(),'message':msg}).encode()
            self.send_response(200);self.send_header('Content-Type','application/json');self.end_headers();self.wfile.write(body);return
